<#
=====================================================================
  SPACE BOOST - FiveM Auto Launcher + Full System Optimizer (MAX)
=====================================================================
  PLAY  : สแกนหา FiveM.exe อัตโนมัติ -> Boost อัตโนมัติ -> เปิด FiveM -> เสียงติ๊ดตอนเข้าเกม -> ปิดโปรแกรม (ค่ายังอยู่)
  BOOST : ปรับเน็ต/ซีพียู/จีพียู/พาวเวอร์/ดิสก์/บริการพื้นหลัง/เมาส์/คีย์บอร์ด แบบเต็มที่สุด
  CLEAN : คืนค่าทุกอย่างกลับเป็นค่าเดิมของเครื่อง (registry, services, NIC, DNS, pagefile, power plan)

  หมายเหตุ: สคริปต์นี้ "ไม่มี" ฟีเจอร์ยกเว้นการสแกนของ Windows Defender ให้กับไฟล์/โปรเซสใดๆ
  เพราะเป็นเทคนิคที่มักถูกใช้ซ่อนมัลแวร์/โปรแกรมโกงจากแอนตี้ไวรัส ไม่ใช่การเพิ่มประสิทธิภาพเกมจริง

  คำเตือนทั่วไป: ปรับ network stack/registry/services ระดับเครื่องทั้งหมด ควรสร้าง System Restore Point
  ก่อนใช้ครั้งแรก และรีสตาร์ทเครื่อง 1 ครั้งหลัง Boost ครั้งแรกเพื่อให้ค่าที่ต้อง reboot (Winsock reset,
  GPU scheduling, pagefile) มีผลเต็มที่ ส่วนที่เหลือมีผลทันทีไม่ต้องรีสตาร์ท
=====================================================================
#>

# --- ลิงก์ของตัวโปรแกรมเอง (ใช้ตอนรันผ่าน  irm <ลิงก์> | iex  แล้วต้อง relaunch เป็น Admin) ---
# KeyManager เมนู 9 จะตั้งค่าบรรทัดนี้ให้ตรง repo ของคุณอัตโนมัติ
$SetupUrl = "https://raw.githubusercontent.com/KCP-dev28/LICENSE/main/setup.ps1"

# --- Robust path detection (fixes $PSCommandPath being $null/"" when compiled to .exe via ps2exe) ---
$script:ScriptPath = if ($PSCommandPath) {
    $PSCommandPath
} elseif ($MyInvocation.MyCommand.Path) {
    $MyInvocation.MyCommand.Path
} else {
    [System.Diagnostics.Process]::GetCurrentProcess().MainModule.FileName
}

# รันผ่าน irm | iex = ไม่มีไฟล์สคริปต์ และ process คือ powershell.exe / pwsh.exe เอง
$script:IsIex = $false
if (-not $PSCommandPath -and -not $MyInvocation.MyCommand.Path) {
    $leafName = [System.IO.Path]::GetFileName($script:ScriptPath).ToLower()
    if ($leafName -eq "powershell.exe" -or $leafName -eq "pwsh.exe") { $script:IsIex = $true }
}

if (-not ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltinRole]::Administrator)) {
    if ($script:IsIex) {
        $relaunch = "[Net.ServicePointManager]::SecurityProtocol=[Net.SecurityProtocolType]::Tls12; irm '$SetupUrl' | iex"
        Start-Process $script:ScriptPath -ArgumentList "-NoProfile -ExecutionPolicy Bypass -Command `"$relaunch`"" -Verb RunAs
    } elseif ($script:ScriptPath -like "*.exe") {
        Start-Process -FilePath $script:ScriptPath -Verb RunAs
    } else {
        Start-Process powershell -ArgumentList "-NoProfile -ExecutionPolicy Bypass -File `"$script:ScriptPath`"" -Verb RunAs
    }
    exit
}

Add-Type -AssemblyName PresentationFramework, PresentationCore, WindowsBase, System.Windows.Forms, System.Drawing, System.Speech, Microsoft.VisualBasic

$ConfigDir  = "$env:APPDATA\SpaceBoost"
$BackupFile = Join-Path $ConfigDir "backup.json"
$ConfigFile = Join-Path $ConfigDir "config.json"
$LicenseFile = Join-Path $ConfigDir "license.dat"
New-Item -ItemType Directory -Force -Path $ConfigDir | Out-Null

# =====================================================================
#  LICENSE / HWID LOCK SYSTEM  (1 Key = 1 เครื่อง)
# =====================================================================
# ระบบใหม่: ใช้ "ลายเซ็นดิจิทัล RSA" -> ในไฟล์ลูกค้ามีแค่ Public Key (ใช้ตรวจลายเซ็นได้อย่างเดียว ใช้ปลอมคีย์ไม่ได้)
# Private Key อยู่กับคุณคนเดียวใน KeyManager.ps1 ห้ามเอาขึ้น GitHub / ห้ามแจกลูกค้า
#
# Public Key: ได้จาก KeyManager.ps1 (เมนู 1 สร้างกุญแจ แล้วเมนู 9 ฝังลงโปรแกรมให้อัตโนมัติ)
$LicensePublicKeyXml = '<RSAKeyValue><Modulus></Modulus><Exponent>AQAB</Exponent></RSAKeyValue>'

# URL ของไฟล์ licenses.json ใน GitHub repo (public) ของคุณ  รูปแบบ:
# https://raw.githubusercontent.com/USERNAME/REPO/main/licenses.json
# ไฟล์นี้มีแค่ hash + สถานะ + ลายเซ็น ไม่มี Key/HWID จริง และถ้าถูกแก้ ลายเซ็นจะไม่ผ่านทันที
$OnlineCheckUrl = "https://raw.githubusercontent.com/KCP-dev28/LICENSE/main/licenses.json"

# เน็ตหลุด/GitHub ล่ม อนุญาตให้ใช้ต่อได้กี่ชั่วโมง นับจากครั้งล่าสุดที่ตรวจผ่าน (0 = เข้มงวด ต้องออนไลน์ทุกครั้ง)
$OfflineGraceHours = 0

function Get-HardwareId {
    <# รวมค่าที่ค่อนข้างคงที่และไม่ซ้ำของเครื่อง แล้วแฮชเป็นรหัส HWID เดียว #>
    $parts = @()
    try { $parts += (Get-CimInstance -ClassName Win32_ComputerSystemProduct -ErrorAction Stop).UUID } catch { $parts += "" }
    try { $parts += (Get-CimInstance -ClassName Win32_BIOS -ErrorAction Stop).SerialNumber } catch { $parts += "" }
    try {
        $disk = Get-CimInstance -ClassName Win32_DiskDrive -ErrorAction Stop | Sort-Object Index | Select-Object -First 1
        $parts += $disk.SerialNumber
    } catch { $parts += "" }
    try { $parts += (Get-CimInstance -ClassName Win32_BaseBoard -ErrorAction Stop).SerialNumber } catch { $parts += "" }

    $raw = ($parts -join "|").Trim()
    $sha256 = [System.Security.Cryptography.SHA256]::Create()
    $hashBytes = $sha256.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($raw))
    $hex = -join ($hashBytes | ForEach-Object { $_.ToString("X2") })
    return $hex.Substring(0, 32)
}

function Format-LicenseKey {
    <# เก็บเฉพาะ A-Z 0-9 แล้วจัดรูปแบบ XXXXX-XXXXX-XXXXX-XXXXX (ลูกค้าวางแบบไม่มีขีดก็ได้) #>
    param([string]$Text)
    if ($null -eq $Text) { return "" }
    $c = ($Text.ToUpper() -replace '[^A-Z0-9]', '')
    if ($c.Length -eq 20) { return ($c -replace '(.{5})(?!$)', '$1-') }
    return $Text.Trim().ToUpper()
}

function Get-LicenseStatus {
    <# ตรวจ "รูปแบบ" ของคีย์เท่านั้น (การอนุมัติจริงมาจากลายเซ็นบน GitHub)
       พารามิเตอร์ -Secret ยังรับไว้เพื่อความเข้ากันได้กับโค้ดเดิม แต่ไม่ได้ใช้แล้ว #>
    param([string]$FullKey, [string]$HWID, [string]$Secret)
    $result = [ordered]@{ Valid = $false; Reason = "invalid"; ExpiryDate = $null }
    if ([string]::IsNullOrWhiteSpace($FullKey)) { $result.Reason = "empty"; return $result }
    $clean = $FullKey.Trim().ToUpper()
    if ($clean -notmatch '^[A-Z0-9]{5}(-[A-Z0-9]{5}){3}$') { return $result }
    $result.Valid = $true; $result.Reason = "ok"
    return $result
}

function Test-LicenseKey {
    param([string]$Key, [string]$HWID, [string]$Secret)
    return (Get-LicenseStatus -FullKey $Key -HWID $HWID).Valid
}

function Get-LicenseFingerprint {
    <# ต้องเหมือน KeyManager.ps1 ทุกตัวอักษร: sha256("HWID|KEY") เป็น hex ตัวเล็ก #>
    param([string]$HWID, [string]$Key)
    $raw = "$($HWID.Trim().ToUpper())|$($Key.Trim().ToUpper())"
    $sha = [System.Security.Cryptography.SHA256]::Create()
    try {
        $bytes = $sha.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($raw))
        return (-join ($bytes | ForEach-Object { $_.ToString("x2") }))
    } finally { $sha.Dispose() }
}

function Test-RegistryEnvelope {
    <#
      ตรวจไฟล์ licenses.json: 1) ลายเซ็น RSA ถูกต้องไหม  2) เวอร์ชัน (seq) ไม่ย้อนหลัง  3) มี fingerprint ของเครื่อง+คีย์นี้ไหม
      4) สถานะ ACTIVE  5) ยังไม่หมดอายุ  -> คืน Blocked=$false เฉพาะเมื่อผ่านครบ
    #>
    param([string]$Raw, [string]$Fp, [datetime]$Now, [switch]$SkipSeqCheck)
    $mk = {
        param($blocked, $reason, $exp)
        [PSCustomObject]@{ Reachable = $true; Blocked = $blocked; Reason = $reason; ExpiryDate = $exp }
    }
    try {
        $envl = $Raw | ConvertFrom-Json -ErrorAction Stop
        if (-not $envl.payload -or -not $envl.sig) { return (& $mk $true "bad_backend_response" $null) }

        $rsa = New-Object System.Security.Cryptography.RSACryptoServiceProvider
        $rsa.FromXmlString($LicensePublicKeyXml)
        $sigOk = $rsa.VerifyData([System.Text.Encoding]::UTF8.GetBytes([string]$envl.payload), "SHA256", [Convert]::FromBase64String([string]$envl.sig))
        if (-not $sigOk) { return (& $mk $true "bad_signature" $null) }

        $p = ([string]$envl.payload) | ConvertFrom-Json -ErrorAction Stop

        # กันเอาไฟล์เก่า (ก่อนที่คุณระงับคีย์) มาสวมแทน
        if (-not $SkipSeqCheck) {
            $seqFile = Join-Path $ConfigDir "registry.seq"
            $last = [int64]0
            if (Test-Path $seqFile) { try { $last = [int64]((Get-Content $seqFile -Raw).Trim()) } catch {} }
            $seq = [int64]$p.seq
            if ($seq -lt $last) { return (& $mk $true "stale_registry" $null) }
            if ($seq -gt $last) { try { Set-Content -Path $seqFile -Value $seq -Encoding ASCII } catch {} }
        }

        $entry = $p.licenses.$Fp
        if ($null -eq $entry) { return (& $mk $true "not_registered" $null) }
        if ("$($entry.s)".Trim().ToUpper() -ne "ACTIVE") { return (& $mk $true "revoked" $null) }

        $e = "$($entry.e)".Trim().ToUpper()
        if ($e -and $e -ne "LIFETIME") {
            $expDate = [datetime]::ParseExact($e, "yyyyMMdd", $null)
            if ($Now.Date -gt $expDate.Date) { return (& $mk $true "expired" $expDate) }
            return (& $mk $false "ok" $expDate)
        }
        return (& $mk $false "ok" $null)
    } catch {
        return (& $mk $true "bad_backend_response" $null)
    }
}

function Test-OnlineRevocation {
    <#
      ตรวจ License กับ GitHub แบบเรียลไทม์ (ใส่ cache-bust ทุกครั้ง) ทุกครั้งที่เปิดโปรแกรม
      - ไฟล์ต้องมีลายเซ็นจาก Private Key ของคุณเท่านั้น
      - Fail-closed: ติดต่อไม่ได้ = ไม่ให้เข้า (ยกเว้นตั้ง $OfflineGraceHours > 0)
    #>
    param([string]$HWID, [string]$Key, [string]$Url)

    if ([string]::IsNullOrWhiteSpace($Url) -or $Url -like "*PASTE_*" -or $LicensePublicKeyXml -like "*PASTE_*") {
        return [PSCustomObject]@{ Reachable = $false; Blocked = $true; Reason = "backend_not_configured"; ExpiryDate = $null }
    }

    $fp    = Get-LicenseFingerprint -HWID $HWID -Key $Key
    $cache = Join-Path $ConfigDir "registry.cache"
    $raw   = $null
    $now   = Get-Date

    try {
        [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
        $sep = if ($Url.Contains("?")) { "&" } else { "?" }
        $bust = [DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds()
        $resp = Invoke-WebRequest -Uri ($Url.Trim() + $sep + "v=" + $bust) -UseBasicParsing -TimeoutSec 8 -Headers @{
            "Cache-Control" = "no-cache"; "Pragma" = "no-cache"
        }
        if ($resp.Content -is [byte[]]) { $raw = [System.Text.Encoding]::UTF8.GetString($resp.Content) } else { $raw = [string]$resp.Content }
        # ใช้เวลาจากเซิร์ฟเวอร์ตรวจวันหมดอายุ กันลูกค้าเลื่อนนาฬิกาเครื่อง
        try { $d = $resp.Headers["Date"]; if ($d) { $now = [datetime]::Parse([string]$d) } } catch {}
    } catch { $raw = $null }

    if ($raw) {
        $r = Test-RegistryEnvelope -Raw $raw -Fp $fp -Now $now
        if (-not $r.Blocked) {
            try { [System.IO.File]::WriteAllText($cache, $raw, (New-Object System.Text.UTF8Encoding($false))) } catch {}
        } elseif ($r.Reason -in @("revoked", "expired", "not_registered")) {
            Remove-Item $cache -Force -ErrorAction SilentlyContinue
        }
        return $r
    }

    # เชื่อมต่อไม่ได้ -> ใช้ช่วงผ่อนผันถ้าตั้งไว้ (ไฟล์ cache ต้องผ่านลายเซ็นเหมือนกัน)
    if ($OfflineGraceHours -gt 0 -and (Test-Path $cache)) {
        try {
            $ageH = ((Get-Date) - (Get-Item $cache).LastWriteTime).TotalHours
            if ($ageH -ge 0 -and $ageH -le $OfflineGraceHours) {
                $r = Test-RegistryEnvelope -Raw (Get-Content $cache -Raw) -Fp $fp -Now (Get-Date) -SkipSeqCheck
                if (-not $r.Blocked) { return $r }
            }
        } catch {}
    }
    return [PSCustomObject]@{ Reachable = $false; Blocked = $true; Reason = "backend_unreachable"; ExpiryDate = $null }
}

function Show-LicenseGate {
    $hwid = Get-HardwareId

    # เคยกรอกคีย์ที่ถูกต้องไว้แล้วในเครื่องนี้หรือยัง (ถ้าใช่ ข้ามหน้า Intro/Key ไปเลย ไม่ต้องรอ)
    $alreadyLicensed = $false
    if (Test-Path $LicenseFile) {
        try {
            $saved = (Get-Content $LicenseFile -Raw -ErrorAction Stop).Trim()
            $savedStatus = Get-LicenseStatus -FullKey $saved -HWID $hwid
            if ($savedStatus.Valid) {
                $onlineCheck = Test-OnlineRevocation -HWID $hwid -Key $saved -Url $OnlineCheckUrl
                if ($onlineCheck.Reachable -and -not $onlineCheck.Blocked) { $alreadyLicensed = $true }
            }
        } catch {}
    }

    # ---------- หน้า Intro + หน้าใส่ Key (WPF, ธีมเดียวกับหน้าโปรแกรมหลัก) ----------
    [xml]$gateXaml = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="SPACE BOOST" Height="520" Width="440"
        WindowStartupLocation="CenterScreen" ResizeMode="NoResize"
        Background="#0B0B14" WindowStyle="None" AllowsTransparency="True">
