      <Setter Property="Cursor" Value="Hand"/>
      <Setter Property="Foreground" Value="White"/>
      <Setter Property="FontWeight" Value="Bold"/>
      <Setter Property="FontSize" Value="15"/>
      <Setter Property="BorderThickness" Value="0"/>
      <Setter Property="Background">
        <Setter.Value>
          <LinearGradientBrush StartPoint="0,0" EndPoint="0,1">
            <GradientStop Color="#8F7DFF" Offset="0"/>
            <GradientStop Color="#6A57E0" Offset="1"/>
          </LinearGradientBrush>
        </Setter.Value>
      </Setter>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="Button">
            <Border x:Name="Bd" CornerRadius="12" Background="{TemplateBinding Background}">
              <Border.Effect>
                <DropShadowEffect x:Name="Glow" Color="#7B6CF6" BlurRadius="0" ShadowDepth="0" Opacity="0"/>
              </Border.Effect>
              <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
            </Border>
            <ControlTemplate.Triggers>
              <Trigger Property="IsMouseOver" Value="True">
                <Setter TargetName="Bd" Property="Effect">
                  <Setter.Value><DropShadowEffect Color="#7B6CF6" BlurRadius="20" ShadowDepth="0" Opacity="0.85"/></Setter.Value>
                </Setter>
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>
    <Style x:Key="GhostBtn" TargetType="Button" BasedOn="{StaticResource GateGlowButton}">
      <Setter Property="Background" Value="#15152E"/>
      <Setter Property="FontSize" Value="12"/>
    </Style>
    <Style x:Key="NiceTextBox" TargetType="TextBox">
      <Setter Property="Background" Value="#15152E"/>
      <Setter Property="Foreground" Value="White"/>
      <Setter Property="CaretBrush" Value="#FFFFFF"/>
      <Setter Property="BorderBrush" Value="#3A2E6E"/>
      <Setter Property="BorderThickness" Value="1"/>
      <Setter Property="Padding" Value="14,12"/>
      <Setter Property="FontSize" Value="16"/>
      <Setter Property="FontWeight" Value="Bold"/>
      <Setter Property="CharacterCasing" Value="Upper"/>
      <Setter Property="Focusable" Value="True"/>
      <Setter Property="IsReadOnly" Value="False"/>
      <Setter Property="IsTabStop" Value="True"/>
      <Setter Property="HorizontalContentAlignment" Value="Left"/>
      <Setter Property="VerticalContentAlignment" Value="Center"/>
      <Setter Property="TextWrapping" Value="NoWrap"/>
      <Setter Property="AcceptsReturn" Value="False"/>
      <Setter Property="Template">
        <Setter.Value>
          <ControlTemplate TargetType="TextBox">
            <Border CornerRadius="10" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}">
              <ScrollViewer x:Name="PART_ContentHost"
                            Margin="{TemplateBinding Padding}"
                            HorizontalScrollBarVisibility="Hidden"
                            VerticalScrollBarVisibility="Hidden"
                            Focusable="False"/>
            </Border>
          </ControlTemplate>
        </Setter.Value>
      </Setter>
    </Style>
  </Window.Resources>

  <Border CornerRadius="16" Background="#0F0F1E" BorderBrush="#3A2E6E" BorderThickness="1">
    <Grid>
      <Grid.RowDefinitions>
        <RowDefinition Height="42"/>
        <RowDefinition Height="*"/>
      </Grid.RowDefinitions>

      <Grid Grid.Row="0" Background="#12122A">
        <Grid.ColumnDefinitions>
          <ColumnDefinition Width="*"/>
          <ColumnDefinition Width="Auto"/>
        </Grid.ColumnDefinitions>
        <TextBlock Text="SPACE BOOST" Foreground="#8A87C4" FontWeight="Bold" FontSize="12" Margin="16,0,0,0" VerticalAlignment="Center"/>
        <Button Name="GateCloseBtn" Grid.Column="1" Content="✕" Width="42" Height="42" Background="Transparent" BorderThickness="0" Foreground="#9A97C9" FontSize="14"/>
      </Grid>

      <Grid Grid.Row="1">

        <!-- ================= หน้า INTRO ================= -->
        <StackPanel Name="IntroPage" VerticalAlignment="Center" HorizontalAlignment="Center" Opacity="1">
