        <!-- ================= หน้าใส่ KEY ================= -->
        <StackPanel Name="KeyPage" VerticalAlignment="Center" HorizontalAlignment="Center" Width="340" Opacity="0" Visibility="Collapsed">
          <Border Width="64" Height="64" Background="#16162E" CornerRadius="16" HorizontalAlignment="Center" Margin="0,0,0,18">
            <Viewbox Width="30" Height="30">
              <Canvas Width="100" Height="100">
                <Polygon Points="50,10 90,90 65,90 50,45 35,90 10,90" Fill="#7B6CF6"/>
              </Canvas>
            </Viewbox>
          </Border>
          <TextBlock Text="ยืนยันสิทธิ์การใช้งาน" Foreground="White" FontWeight="Bold" FontSize="20" HorizontalAlignment="Center"/>
          <TextBlock Text="กรอก License Key ที่ได้รับจากผู้ขาย" Foreground="#8A87C4" FontSize="12" HorizontalAlignment="Center" Margin="0,4,0,20"/>

          <TextBlock Text="HWID เครื่องนี้ (ส่งให้ผู้ขายเพื่อขอ Key)" Foreground="#6A6790" FontSize="11" Margin="2,0,0,6"/>
          <Border Background="#15152E" CornerRadius="10" Padding="12,10" Margin="0,0,0,18">
