              <Button Name="CopyHwidBtn" Grid.Column="1" Content="คัดลอก" Style="{StaticResource GhostBtn}" Width="70" Height="30" Margin="8,0,0,0"/>
            </Grid>
          </Border>

          <TextBlock Text="License Key" Foreground="#6A6790" FontSize="11" Margin="2,0,0,6"/>
          <TextBox Name="KeyInputBox" Style="{StaticResource NiceTextBox}" Height="46"
                   Margin="0,0,0,8" MaxLength="80" ToolTip="คลิกช่องนี้แล้ววาง License Key (Ctrl+V)"/>
          <TextBlock Name="ErrorMsg" Text="" Foreground="#FF6B6B" FontSize="11" Margin="2,0,0,10" Visibility="Collapsed" TextWrapping="Wrap"/>

          <Button Name="ConfirmBtn" Content="ยืนยันคีย์ / ENTER" Height="50" Style="{StaticResource GateGlowButton}" Margin="0,4,0,14"/>
          <TextBlock Text="ยังไม่มีคีย์? ติดต่อ discord.gg/HOWLSHOP" Foreground="#5A5780" FontSize="11" HorizontalAlignment="Center"/>
        </StackPanel>

      </Grid>
    </Grid>
  </Border>
</Window>
"@

    $gateReader  = New-Object System.Xml.XmlNodeReader $gateXaml
    $GateWindow  = [Windows.Markup.XamlReader]::Load($gateReader)
    $GateCloseBtn = $GateWindow.FindName("GateCloseBtn")
    $IntroPage    = $GateWindow.FindName("IntroPage")
    $KeyPage      = $GateWindow.FindName("KeyPage")
    $LoadingFill  = $GateWindow.FindName("LoadingFill")
    $HwidText     = $GateWindow.FindName("HwidText")
    $CopyHwidBtn  = $GateWindow.FindName("CopyHwidBtn")
    $KeyInputBox  = $GateWindow.FindName("KeyInputBox")
    $ErrorMsg     = $GateWindow.FindName("ErrorMsg")
    $ConfirmBtn   = $GateWindow.FindName("ConfirmBtn")

    $GateWindow.Add_MouseLeftButtonDown({ $GateWindow.DragMove() })
    $script:LicenseOK = $false
    $HwidText.Text = $hwid

    $GateCloseBtn.Add_Click({ $script:LicenseOK = $false; $GateWindow.Close() })

    $CopyHwidBtn.Add_Click({
        try {
            [System.Windows.Forms.Clipboard]::SetText($hwid)
            $CopyHwidBtn.Content = "คัดลอกแล้ว"
        } catch {}
    })

    $doConfirm = {
        $entered = Format-LicenseKey $KeyInputBox.Text
        $status = Get-LicenseStatus -FullKey $entered -HWID $hwid
        if ($status.Valid) {
            $onlineCheck = Test-OnlineRevocation -HWID $hwid -Key $entered -Url $OnlineCheckUrl
            if ($onlineCheck.Blocked) {
                $ErrorMsg.Text = switch ($onlineCheck.Reason) {
                    "revoked" { "Key นี้ถูกระงับการใช้งานโดยผู้ขาย กรุณาติดต่อผู้ขาย" }
                    "not_registered" { "Key นี้ไม่ตรงกับเครื่องนี้ หรือผู้ขายยังไม่ได้เปิดใช้งาน กรุณาติดต่อผู้ขาย" }
                    "expired" { "Key นี้หมดอายุแล้ว (วันที่ $($onlineCheck.ExpiryDate.ToString('dd/MM/yyyy'))) กรุณาติดต่อผู้ขายเพื่อต่ออายุ" }
                    "bad_signature" { "ข้อมูล License ไม่ผ่านการตรวจสอบลายเซ็น (อาจถูกดัดแปลง) กรุณาลองใหม่หรือติดต่อผู้ขาย" }
                    "stale_registry" { "ข้อมูล License ไม่เป็นปัจจุบัน กรุณาลองใหม่อีกครั้ง" }
                    "backend_not_configured" { "ยังไม่ได้ตั้งค่าระบบ License Server" }
                    "backend_unreachable" { "เชื่อมต่อระบบ License Server ไม่ได้ กรุณาตรวจสอบอินเทอร์เน็ต" }
                    default { "ไม่สามารถยืนยัน License กับระบบหลังบ้านได้" }
                }
                $ErrorMsg.Visibility = "Visible"
                $KeyInputBox.SelectAll()
                $KeyInputBox.Focus() | Out-Null
                return
            }
            Set-Content -Path $LicenseFile -Value $entered.Trim().ToUpper() -Encoding UTF8
            $script:LicenseOK = $true
            $GateWindow.Close()
        } else {
            $ErrorMsg.Text = switch ($status.Reason) {
                "expired" { "Key นี้หมดอายุแล้วเมื่อวันที่ $($status.ExpiryDate.ToString('dd/MM/yyyy')) กรุณาติดต่อผู้ขายเพื่อต่ออายุ" }
                default   { "รูปแบบ Key ไม่ถูกต้อง (ต้องเป็น XXXXX-XXXXX-XXXXX-XXXXX)" }
            }
            $ErrorMsg.Visibility = "Visible"
            $KeyInputBox.SelectAll()
            $KeyInputBox.Focus() | Out-Null
        }
    }
    $ConfirmBtn.Add_Click($doConfirm)
    $KeyInputBox.Add_PreviewMouseDown({
        if (-not $KeyInputBox.IsKeyboardFocusWithin) {
            $KeyInputBox.Focus() | Out-Null
            $KeyInputBox.CaretIndex = $KeyInputBox.Text.Length
        }
    })
    $KeyInputBox.Add_KeyDown({ param($s, $e) if ($e.Key -eq "Return") { & $doConfirm; $e.Handled = $true } })
    $KeyInputBox.Add_TextChanged({
        # รองรับการวางคีย์ที่มีช่องว่าง/ขึ้นบรรทัดใหม่จาก Discord
        $clean = ($KeyInputBox.Text -replace '[
	 ]','').ToUpper()
        if ($clean -ne $KeyInputBox.Text) {
            $pos = $clean.Length
            $KeyInputBox.Text = $clean
            $KeyInputBox.CaretIndex = $pos
        }
    })

    # ---------- แถบโหลดของหน้า Intro วิ่งเต็มใน ~1.6 วิ แล้วสลับหน้า ----------
    $fillAnim = New-Object System.Windows.Media.Animation.DoubleAnimation(0, 220, (New-Object System.Windows.Duration([TimeSpan]::FromSeconds(1.6))))
    $LoadingFill.BeginAnimation([System.Windows.FrameworkElement]::WidthProperty, $fillAnim)

    $introTimer = New-Object System.Windows.Threading.DispatcherTimer
    $introTimer.Interval = [TimeSpan]::FromSeconds(1.7)
    $introTimer.Add_Tick({
        $introTimer.Stop()
        $fadeOut = New-Object System.Windows.Media.Animation.DoubleAnimation(1, 0, (New-Object System.Windows.Duration([TimeSpan]::FromSeconds(0.35))))
        $fadeOut.add_Completed({
            $IntroPage.Visibility = "Collapsed"
            if ($alreadyLicensed) {
                # มีคีย์ที่ใช้ได้อยู่แล้ว -> ข้ามหน้า Key ไปเข้าโปรแกรมเลย
                $script:LicenseOK = $true
                $GateWindow.Close()
            } else {
                $KeyPage.Visibility = "Visible"
                $fadeIn = New-Object System.Windows.Media.Animation.DoubleAnimation(0, 1, (New-Object System.Windows.Duration([TimeSpan]::FromSeconds(0.35))))
                $KeyPage.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $fadeIn)
                $KeyInputBox.Focus() | Out-Null
            }
        })
        $IntroPage.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $fadeOut)
    })
    $introTimer.Start()

    $GateWindow.ShowDialog() | Out-Null
    return $script:LicenseOK
}

