$reader = New-Object System.Xml.XmlNodeReader $xaml
$window = [Windows.Markup.XamlReader]::Load($reader)
$StatusText = $window.FindName("StatusText"); $ModeText = $window.FindName("ModeText")
$PlayBtn = $window.FindName("PlayBtn"); $BoostBtn = $window.FindName("BoostBtn"); $CleanBtn = $window.FindName("CleanBtn")
$CloseBtn = $window.FindName("CloseBtn")
$SnowCanvas = $window.FindName("SnowCanvas")
$window.Add_MouseLeftButtonDown({ $window.DragMove() })
$CloseBtn.Add_Click({ $window.Close() })

# ---------- Hover sound on buttons: synthesized short "pop" ----------
function New-PopSoundStream {
    $sampleRate = 8000
    $duration = 0.06
    $samples = [int]($sampleRate * $duration)
    $ms = New-Object System.IO.MemoryStream
    $bw = New-Object System.IO.BinaryWriter($ms)
    $dataSize = $samples * 2
    $bw.Write([System.Text.Encoding]::ASCII.GetBytes("RIFF"))
    $bw.Write([int32]($36 + $dataSize))
    $bw.Write([System.Text.Encoding]::ASCII.GetBytes("WAVE"))
    $bw.Write([System.Text.Encoding]::ASCII.GetBytes("fmt "))
    $bw.Write([int32]16)
    $bw.Write([int16]1)               # PCM
    $bw.Write([int16]1)               # mono
    $bw.Write([int32]$sampleRate)
    $bw.Write([int32]($sampleRate * 2))
    $bw.Write([int16]2)
    $bw.Write([int16]16)
    $bw.Write([System.Text.Encoding]::ASCII.GetBytes("data"))
    $bw.Write([int32]$dataSize)
    for ($i = 0; $i -lt $samples; $i++) {
        $t = $i / $sampleRate
        $freq = 1300 - (950 * ($i / $samples))          # quick downward pitch sweep = "pop"
        $env  = [math]::Exp(-$i / ($samples * 0.22))     # fast decay
        $val  = [math]::Sin(2 * [math]::PI * $freq * $t) * $env * 0.9
        $bw.Write([int16]($val * 32000))
    }
    $bw.Flush(); $ms.Position = 0
    return $ms
}
$script:PopPlayer = New-Object System.Media.SoundPlayer
$script:PopPlayer.Stream = New-PopSoundStream
$script:PopPlayer.Load()
foreach ($b in @($PlayBtn, $BoostBtn, $CleanBtn)) {
    $b.Add_MouseEnter({ try { $script:PopPlayer.Play() } catch {} })
}

# ---------- Snow effect ----------
$script:Flakes = @()
$rand = New-Object System.Random
for ($i = 0; $i -lt 45; $i++) {
    $size = $rand.Next(2, 6)
    $flake = New-Object System.Windows.Shapes.Ellipse
    $flake.Width = $size; $flake.Height = $size
    $flake.Fill = [System.Windows.Media.Brushes]::White
    $flake.Opacity = 0.2 + ($rand.NextDouble() * 0.6)
    $x = $rand.Next(0, 900); $y = $rand.Next(-300, 300)
    [System.Windows.Controls.Canvas]::SetLeft($flake, $x)
    [System.Windows.Controls.Canvas]::SetTop($flake, $y)
    $SnowCanvas.Children.Add($flake) | Out-Null
    $script:Flakes += [PSCustomObject]@{
        Shape = $flake; X = [double]$x; Y = [double]$y
        Speed = 0.4 + ($rand.NextDouble() * 1.2)
        Sway  = ($rand.NextDouble() - 0.5) * 0.6
        Phase = $rand.NextDouble() * 6.28
    }
}
$script:snowTick = 0
$snowTimer = New-Object System.Windows.Threading.DispatcherTimer
$snowTimer.Interval = [TimeSpan]::FromMilliseconds(33)
$snowTimer.Add_Tick({
    $script:snowTick += 0.05
    foreach ($f in $script:Flakes) {
        $f.Y += $f.Speed
        $swayX = $f.X + [math]::Sin($script:snowTick + $f.Phase) * $f.Sway
        if ($f.Y -gt 300) { $f.Y = -10; $f.X = $rand.Next(0, 900) }
        [System.Windows.Controls.Canvas]::SetTop($f.Shape, $f.Y)
        [System.Windows.Controls.Canvas]::SetLeft($f.Shape, $swayX)
    }
})
$snowTimer.Start()

function Set-Status($t) { $StatusText.Text = "● $t" }
function Set-Buttons($e) { $PlayBtn.IsEnabled = $e; $BoostBtn.IsEnabled = $e; $CleanBtn.IsEnabled = $e }

$script:Tts = New-Object System.Speech.Synthesis.SpeechSynthesizer
try {
    $femaleVoice = $script:Tts.GetInstalledVoices() | Where-Object {
        $_.VoiceInfo.Gender -eq "Female" -or $_.VoiceInfo.Name -match "Zira|Susan|Hazel"
    } | Select-Object -First 1
    if ($femaleVoice) { $script:Tts.SelectVoice($femaleVoice.VoiceInfo.Name) }
    else { $script:Tts.SelectVoiceByHints([System.Speech.Synthesis.VoiceGender]::Female) }
} catch {}
# เสียงต้อนรับตอนเปิดโปรแกรม และเสียงตอนกด PLAY (ฝัง base64 ในสคริปต์)
$script:WelcomeB64 = ''
$script:EnjoyB64 = ''
function Play-Base64Sound([string]$b64) {
    if (-not $b64) { return }
    try {
        $bytes = [Convert]::FromBase64String($b64)
        $ms = New-Object System.IO.MemoryStream(,$bytes)
        $p = New-Object System.Media.SoundPlayer
        $p.Stream = $ms
        $p.Play()
    } catch {}
}

$script:Tts.Rate   = -1
$script:Tts.Volume = 100

# ตำแหน่งไฟล์เสียงจริง (มนุษย์อัด/โหลดมา) - วางไฟล์ boost_success.wav หรือ .mp3 ไว้ในโฟลเดอร์ sounds
$script:SoundsDir = if ($script:IsIex) { Join-Path $ConfigDir "sounds" } else { Join-Path (Split-Path -Parent $script:ScriptPath) "sounds" }
$script:BoostSuccessWav = Join-Path $script:SoundsDir "boost_success.wav"
$script:BoostSuccessMp3 = Join-Path $script:SoundsDir "boost_success.mp3"

# เสียง Boost Success ที่ฝังไว้ในสคริปต์เอง (base64) - ใช้ได้แม้ไม่มีโฟลเดอร์ sounds แนบมาด้วย
$script:BoostSuccessB64 = ''


function Say-Text([string]$text) {
    # 1) ลองเล่นเสียงที่ฝังอยู่ในสคริปต์เอง (base64) ก่อน - ไม่ต้องพึ่งไฟล์ภายนอกเลย
    if ($script:BoostSuccessB64) {
        try {
            $bytes = [Convert]::FromBase64String($script:BoostSuccessB64)
            $ms = New-Object System.IO.MemoryStream(,$bytes)
            $p = New-Object System.Media.SoundPlayer
            $p.Stream = $ms
            $p.Play()
            return
        } catch {}
    }
    # 2) ถ้าไม่มีเสียงฝัง ลองไฟล์ wav/mp3 ภายนอกที่วางไว้ในโฟลเดอร์ sounds
    if (Test-Path $script:BoostSuccessWav) {
        try {
            $p = New-Object System.Media.SoundPlayer $script:BoostSuccessWav
            $p.Play()
            return
        } catch {}
    }
    if (Test-Path $script:BoostSuccessMp3) {
        try {
            $media = New-Object System.Windows.Media.MediaPlayer
            $media.Open([Uri]$script:BoostSuccessMp3)
            $media.Play()
            return
        } catch {}
    }
    # 3) ไม่เจอเสียงใดเลย -> ใช้เสียงพูดสังเคราะห์ (TTS) แทน
    try { $script:Tts.SpeakAsyncCancelAll(); $script:Tts.SpeakAsync($text) | Out-Null } catch {}
}

$BoostBtn.Add_Click({
    Set-Buttons $false; $ModeText.Text = "● BOOSTING"; Set-Status "กำลัง Boost แบบเต็มพิกัด (อาจใช้เวลา 10-30 วิ)..."
    [System.Windows.Forms.Application]::DoEvents()
    Apply-Boost
    $ModeText.Text = "● BOOSTED"
    Set-Status "Boost เรียบร้อย - แนะนำรีสตาร์ทเครื่อง 1 ครั้งเพื่อให้ค่า GPU/Winsock/Pagefile มีผลเต็มที่"
    Say-Text "Boost Success"
    Set-Buttons $true
})
$CleanBtn.Add_Click({
    Set-Buttons $false; Set-Status "กำลังคืนค่าทั้งหมด..."; [System.Windows.Forms.Application]::DoEvents()
    $ok = Revert-Boost
    $ModeText.Text = "● READY"
    Set-Status $(if ($ok) { "คืนค่าเรียบร้อย" } else { "ยังไม่เคยกด Boost มาก่อน" })
    Set-Buttons $true
})
$PlayBtn.Add_Click({
    try {
        Set-Buttons $false
        Set-Status "กำลังสแกนหา FiveM..."
        [System.Windows.Forms.Application]::DoEvents()

        $path = Find-FiveMExe
        if (-not $path) {
            Set-Status "หาไม่เจอ กรุณาเลือกไฟล์ FiveM.exe เอง"
            $dlg = New-Object System.Windows.Forms.OpenFileDialog
            try {
                $dlg.Filter = "FiveM.exe|FiveM.exe"
                $dlg.Title = "เลือกไฟล์ FiveM.exe"
                if ($dlg.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) { $path = [string]$dlg.FileName }
            } finally { if ($dlg) { $dlg.Dispose() } }
        }

        if (-not $path -or -not (Test-Path -LiteralPath $path)) {
            Set-Status "ไม่พบไฟล์ FiveM.exe"
            Set-Buttons $true
            return
        }

        Save-FiveMPath $path
        $ModeText.Text = "● BOOSTING"
        Set-Status "กำลัง Boost..."
        [System.Windows.Forms.Application]::DoEvents()
        try { Apply-Boost } catch { }

        $ModeText.Text = "● LAUNCHING FIVEM"
        Set-Status "กำลังเปิด FiveM แบบไม่ใช้สิทธิ์ Administrator..."
        [System.Windows.Forms.Application]::DoEvents()

        $launched = Start-FiveMNonElevated -Path $path
        if (-not $launched) {
            Set-Status "เปิด FiveM ไม่สำเร็จ กรุณาตรวจสอบสิทธิ์ของ FiveM.exe"
            Set-Buttons $true
            return
        }

        Set-Status "เปิด FiveM แล้ว โปรแกรมนี้จะปิดใน 2 วินาที..."
        $ModeText.Text = "● FIVEM LAUNCHED"
        [System.Windows.Forms.Application]::DoEvents()
        Start-Sleep -Seconds 2
        $window.Close()
    } catch {
        Set-Buttons $true
        $msg = [string]$_.Exception.Message
        if ([string]::IsNullOrWhiteSpace($msg)) { $msg = "เกิดข้อผิดพลาดที่ไม่ทราบสาเหตุ" }
        Set-Status "PLAY ผิดพลาด: $msg"
    }
})

Play-Base64Sound $script:WelcomeB64
$window.ShowDialog() | Out-Null
